mapper.update:
UPDATE fin_expense_verify_batch
SET status = 'REVERSED', reverse_by = #{reverseBy}, reverse_time = #{reverseTime},
    reverse_reason = #{reason}, reverse_request_id = #{requestId}, version = version + 1,
    update_time = #{reverseTime}
WHERE batch_id = #{batchId} AND tenant_id = #{tenantId} AND dept_id = #{deptId}
  AND status = 'VERIFIED' AND version = #{version}

UPDATE fin_advance SET status=#{originalStatus}, verify_by=NULL, verify_time=NULL, update_time=SYSDATE()
WHERE advance_id=#{advanceId} AND tenant_id=#{tenantId} AND dept_id=#{deptId} AND status='1' AND del_flag='0'
  AND verify_by <=> #{verifyBy} AND verify_time <=> #{verifyTime}

UPDATE fin_advance SET status='0', verify_by=NULL, verify_time=NULL, del_flag='2', update_time=SYSDATE()
WHERE advance_id=#{advanceId} AND tenant_id=#{tenantId} AND dept_id=#{deptId}
  AND status=#{expectedStatus} AND del_flag='0' AND verify_by <=> #{verifyBy} AND verify_time <=> #{verifyTime}

mapper.select:
SELECT batch_id, batch_no, request_id, tenant_id, dept_id, total_expense_amount, total_advance_amount, difference_amount, status, source_type, verify_by, verify_time, reverse_by, reverse_time, reverse_reason, reverse_request_id, version, create_time, update_time FROM fin_expense_verify_batch WHERE tenant_id = #{tenantId} AND dept_id = #{deptId}
AND batch_no LIKE CONCAT('%', #{query.batchNo}, '%')
AND status = #{query.status}
AND source_type = #{query.sourceType}
AND verify_by LIKE CONCAT('%', #{query.verifyBy}, '%')
AND verify_time >= #{query.params.beginTime}
AND verify_time < DATE_ADD(#{query.params.endTime}, INTERVAL 1 DAY)
ORDER BY verify_time DESC, batch_id DESC
